"""Generates memory_worker/models.py from the contract the TypeScript side publishes.

uv run python scripts/generate_models.py          # write
uv run python scripts/generate_models.py --check  # fail if the committed file is stale
"""

from __future__ import annotations

import subprocess
import sys
import tempfile
from pathlib import Path

from memory_worker.contract import CONTRACT_SCHEMA, WORKER_DIR

OUTPUT = WORKER_DIR / "memory_worker" / "models.py"
HEADER = (
    '"""Pydantic models of the shared memory contract. GENERATED by scripts/generate_models.py '
    'from packages/memory-contract/generated/contract.json; do not edit by hand."""\n\n'
)


def generate(target: Path) -> None:
    subprocess.run(
        [
            sys.executable,
            "-m",
            "datamodel_code_generator",
            "--input",
            str(CONTRACT_SCHEMA),
            "--input-file-type",
            "jsonschema",
            "--output",
            str(target),
            "--output-model-type",
            "pydantic_v2.BaseModel",
            "--use-standard-collections",
            "--use-union-operator",
            "--use-schema-description",
            "--target-python-version",
            "3.13",
            "--formatters",
            "ruff-format",
            "--disable-timestamp",
            "--use-title-as-name",
        ],
        check=True,
    )
    target.write_text(HEADER + target.read_text())


def main(argv: list[str]) -> int:
    if "--check" in argv:
        # Inside the worker directory so ruff-format picks up the same line length.
        with tempfile.TemporaryDirectory(dir=WORKER_DIR, prefix=".models-check-") as tmp:
            fresh = Path(tmp) / "models.py"
            generate(fresh)
            if not OUTPUT.exists() or fresh.read_text() != OUTPUT.read_text():
                print(
                    "memory_worker/models.py is stale; run scripts/generate_models.py",
                    file=sys.stderr,
                )
                return 1
        print("models.py matches the contract")
        return 0
    generate(OUTPUT)
    print(f"wrote {OUTPUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
